import { interleavedBuckSample } from './rack-power-model.js';

export function renderClementePower() {
  return `<div class="clemente-user-figure"><img src="../assets/references/clemente-gb300-user.png" alt="User-supplied illustration: inside Meta’s Clemente GB300 compute tray, the 51 V rack bus feeds the NVIDIA-designed power distribution board, which produces 12 V before local regulators supply processor rails."><a class="vrm-source" href="https://www.opencompute.org/documents/clemente-compute-tray-ocp-specification-final-pdf" target="_blank" rel="noopener">Meta / OCP · Clemente specification, §§7.2 and 8.1</a></div>`;
}

const colors = ['var(--teal)', 'var(--amber)'];
const path = (values, x, y, width, height, low, high) => values.map((v, i) => `${i ? 'L' : 'M'}${(x + width * i / (values.length - 1)).toFixed(2)} ${(y + height * (high - v) / (high - low)).toFixed(2)}`).join(' ');
const coil = (x, y) => `<path d="M${x} ${y}h12${Array.from({length:4},()=> 'a9 12 0 0 1 18 0').join('')}h12" fill="none" stroke="currentColor" stroke-width="3"/>`;

function switchingCircuit() {
  return `<svg class="vrm-circuit" viewBox="0 0 500 400" role="img" aria-labelledby="switching-circuit-title"><title id="switching-circuit-title">One regulator with two switching branches and inductors feeding one output rail, a capacitor and a load.</title><text x="250" y="29" text-anchor="middle" class="vrm-panel-title">One VRM · two phases</text><path d="M42 96V256M42 96H85M42 256H85" fill="none" stroke="var(--ink)" stroke-width="3"/><text x="42" y="68" text-anchor="middle" class="vrm-label">12 V</text>${[96,256].map((y,i)=>`<g color="${colors[i]}"><rect x="85" y="${y-33}" width="112" height="66" rx="9" fill="var(--surface)" stroke="currentColor" stroke-width="2"/><text x="141" y="${y+6}" text-anchor="middle" class="vrm-label" style="fill:currentColor">Switch ${i?'B':'A'}</text><path d="M197 ${y}H225" stroke="currentColor" stroke-width="3"/><circle cx="213" cy="${y}" r="4" fill="currentColor"/>${coil(225,y)}<path d="M321 ${y}H360" stroke="currentColor" stroke-width="3"/><text x="275" y="${y-26}" text-anchor="middle" class="vrm-label" style="fill:currentColor">Inductor</text></g>`).join('')}<path d="M360 96V256M360 176H403" fill="none" stroke="var(--ink)" stroke-width="3"/><circle cx="360" cy="176" r="4" fill="var(--ink)"/><rect x="403" y="140" width="76" height="72" rx="9" fill="var(--surface)" stroke="var(--ink)" stroke-width="2"/><text x="441" y="182" text-anchor="middle" class="vrm-label">Load</text><path d="M382 176V281M366 281H398M366 290H398M382 290V321M367 321H397M372 328H392M377 335H387" stroke="var(--ink)" stroke-width="2" fill="none"/><text x="430" y="119" text-anchor="middle" class="vrm-label">3 V rail</text><text x="382" y="368" text-anchor="middle" class="vrm-label">Output capacitor</text></svg>`;
}

function switchingWaveforms() {
  const samples=Array.from({length:801},(_,i)=>interleavedBuckSample(i/400));
  const left=60, width=480;
  const axis=(top,height,low,high)=>`<path d="M${left} ${top}V${top+height}H${left+width}" stroke="var(--line)" fill="none"/>${[low,high].map(value=>`<text x="${left-12}" y="${top+height*(high-value)/(high-low)+5}" text-anchor="end" class="vrm-tick">${value}</text>`).join('')}`;
  const curves=(key,top,height,low,high)=>[0,1].map((phase)=>`<path d="${path(samples.map(s=>s.phases[phase][key]),left,top,width,height,low,high)}" fill="none" stroke="${colors[phase]}" stroke-width="2.7"/>`).join('');
  return `<svg class="vrm-waveforms" viewBox="0 0 565 480" role="img" aria-labelledby="switching-wave-title switching-wave-desc"><title id="switching-wave-title">Staggered switch pulses and inductor currents</title><desc id="switching-wave-desc">Switch A and B pulse from zero to 12 volts a half cycle apart. Each inductor current ranges from 17 to 23 amperes. The combined current ranges from 38 to 42 amperes: smaller peak-to-peak ripple even though it carries both phases’ current.</desc><text x="60" y="24" class="vrm-panel-title">Switch-node voltage (V)</text><text x="453" y="24" style="fill:var(--teal)" class="vrm-label">A</text><text x="510" y="24" style="fill:var(--amber)" class="vrm-label">B</text>${axis(48,77,0,12)}${curves('switchVolts',48,77,0,12)}<text x="60" y="181" class="vrm-panel-title">Inductor current (A)</text>${axis(205,77,17,23)}${curves('currentAmps',205,77,17,23)}<text x="60" y="340" class="vrm-panel-title">A + B into the rail (A)</text>${axis(364,77,37,43)}<path d="M60 402.5H540" stroke="var(--line)" stroke-dasharray="4 4"/><path d="${path(samples.map(s=>s.totalAmps),left,364,width,77,37,43)}" fill="none" stroke="var(--ink)" stroke-width="3"/><text x="540" y="472" text-anchor="end" class="vrm-label">Time →</text></svg>`;
}

export function renderVRMSwitching() {
  return `<div class="vrm-switching"><div class="vrm-switching-panels">${switchingCircuit()}${switchingWaveforms()}</div><a class="vrm-source" href="https://www.ti.com/lit/an/slyt449/slyt449.pdf" target="_blank" rel="noopener">Texas Instruments · Multiphase buck conversion</a></div>`;
}
